        const RR_DESC = {
            'infectologia': 'HIV/aids, ISTs, Tuberculose, Hanseníase',
            'cardiologia': 'Síndromes coronarianas, Arritmias, Insuficiência cardíaca',
            'endocrinologia': 'Diabetes mellitus, Tireoide, Adrenal, Hipófise',
            'gastroenterologia': 'DRGE, Doenças inflamatórias intestinais, Pâncreas',
            'hepatologia': 'Nomenclatura atualizada, Hepatopatias, Cirrose',
            'pneumologia': 'Asma, DPOC, Pneumonia, Tromboembolismo',
            'neurologia': 'Cefaleias, AVC, Epilepsia, Demências',
            'reumatologia': 'Artrite reumatoide, Lúpus, Espondiloartropatias',
            'nefrologia': 'Doença renal crônica, Injúria renal aguda, Distúrbios eletrolíticos',
            'hematologia': 'Anemias, Neoplasias hematológicas, Coagulação',
            'dermatologia': 'Infecções de pele, Dermatoses inflamatórias, Câncer de pele',
            'oftalmologia': 'Olho vermelho, Glaucoma agudo, Emergências oftalmológicas',
            'otorrinolaringologia': 'Vertigem, Perda auditiva, Epistaxe',
            'obstetricia': 'Pré-natal, Síndromes hipertensivas, Parto e puerpério',
            'ginecologia': 'Contracepção, Colo do útero, Mama, Climatério',
            'psiquiatria': 'Transtornos de ansiedade, Psicoses, Depressão',
            'pediatria-completo': 'Neonatologia, Crescimento e desenvolvimento, Imunizações',
            'medicina-preventiva': 'Vigilância em saúde, Promoção da saúde, Estratégias de SUS',
            'cirurgia-geral': 'Trauma, Gastroenterologia, Abdome agudo'
        };

        function getLastReadTopic() {
            const data = getProgressData();
            let bestKey = null;
            let bestTime = -1;
            Object.keys(data).forEach(key => {
                const entry = data[key];
                if (entry && entry.readChapters && entry.readChapters.length > 0 && entry.lastAccess > bestTime) {
                    bestKey = key;
                    bestTime = entry.lastAccess;
                }
            });
            return bestKey;
        }

        function renderLastReadCard() {
            const container = document.getElementById('inicioLastRead');
            if (!container) return;

            const topicKey = getLastReadTopic();
            const topic = topicKey ? RAPID_REVIEW_DATA[topicKey] : null;

            if (!topic) {
                container.innerHTML = '';
                return;
            }

            const progress = calculateProgress(topicKey);
            const icon = RR_ICONS[topicKey] || '';
            const desc = RR_DESC[topicKey] || '';
            const existingCard = container.querySelector('.rr-card');

            // Durante a leitura, atualizamos somente os dados variáveis. Isso
            // evita recriar o card e disparar novamente a animação de entrada.
            if (existingCard && existingCard.getAttribute('data-topic') === `${topicKey}-inicio`) {
                const label = existingCard.querySelector('.rr-progress-label');
                const fill = existingCard.querySelector('.rr-progress-fill');
                if (label) label.textContent = `${progress}% lido`;
                if (fill) fill.style.width = `${progress}%`;
                existingCard.querySelector('.rr-card-badge')?.remove();
                return;
            }

            container.innerHTML = `
                <div class="rr-card highlighted" onclick="openReader('${topicKey}')" data-topic="${topicKey}-inicio">
                    <div class="rr-continue-badge">Continuar</div>
                    <div class="rr-card-icon">${icon}</div>
                    <div class="rr-card-content">
                        <div class="rr-card-header">
                            <div class="rr-card-title">${topic.title}</div>
                        </div>
                        <div class="rr-card-description">${desc}</div>
                        <div class="rr-card-status">
                            <span class="rr-progress-label">${progress}% lido</span>
                        </div>
                        <div class="rr-progress-bar">
                            <div class="rr-progress-fill" style="width: ${progress}%"></div>
                        </div>
                    </div>
                    <div class="rr-card-arrow">›</div>
                </div>
            `;
        }

        function markChapterAsRead(topicKey, chapterNum) {
            const data = getProgressData();
            if (!data[topicKey]) {
                data[topicKey] = { lastAccess: Date.now(), readChapters: [] };
            }
            if (data[topicKey].readChapters.includes(chapterNum)) return;

            data[topicKey].readChapters.push(chapterNum);
            saveProgressData(data);
            updateAllCardProgress();
            renderLastReadCard();
        }

        function splitRapidReviewBody(bodyHtml, maxCharacters = 3600) {
            const template = document.createElement('template');
            template.innerHTML = bodyHtml || '';
            const nodes = Array.from(template.content.childNodes).filter(node => {
                return node.nodeType === Node.ELEMENT_NODE || (node.nodeType === Node.TEXT_NODE && node.textContent.trim());
            });
            const chunks = [];
            let current = '';
            let currentLength = 0;

            nodes.forEach(node => {
                const html = node.nodeType === Node.ELEMENT_NODE ? node.outerHTML : node.textContent;
                const length = (node.textContent || '').length;
                if (current && currentLength + length > maxCharacters) {
                    chunks.push(current);
                    current = '';
                    currentLength = 0;
                }
                current += html;
                currentLength += length;
            });

            if (current) chunks.push(current);
            return chunks.length ? chunks : [''];
        }


        async function downloadRapidReviewPdf() {
            const topic = RAPID_REVIEW_DATA[readerState.topicKey];
            if (!topic) return;
            const progress = document.querySelector('.reader-pdf-btn');
            beginPdfDownloadProgress(progress);
            if (!topic.sections?.length) {
                setPdfDownloadProgress(progress, 0, false);
                return;
            }
            try {
                setPdfDownloadProgress(progress, 15, true);
                await ensurePdfLibsLoaded();
                setPdfDownloadProgress(progress, 40, true);
                const bytes = await TryckPdf.buildRapidReviewPdf({ topic });
                setPdfDownloadProgress(progress, 96, true);
                await waitForPdfProgressPaint();
                const fileTitle = (topic.title || topic.area || 'rapid-review').replace(/[^\p{L}\p{N}]+/gu, '-');
                TryckPdf.downloadBytes(bytes, `trycktrack-${fileTitle}.pdf`);
                setPdfDownloadProgress(progress, 100, false);
            } catch (err) {
                console.error('Falha ao gerar PDF do Rapid Review', err);
                setPdfDownloadProgress(progress, 0, false);
                if (typeof revealQuestionNotice === 'function') revealQuestionNotice(pdfErrorNotice(err, 'Não foi possível gerar o PDF. Tente novamente.'));
            }
        }

        function openReader(topicKey) {
            checkAndResetProgressAfter24h(topicKey);
            highlightCurrentCard(topicKey);
            readerState = { topicKey, sectionIndex: 0, subIndex: 0 };
            renderReaderContent();
            applyReaderFontSize(Number(localStorage.getItem(READER_FONT_KEY)) || 16);
            document.getElementById('readerView').classList.add('active');
            restoreReaderPosition(topicKey);
            updateAllCardProgress();
        }

        function closeReader() {
            clearTimeout(readerPositionSaveTimer);
            saveCurrentReaderPosition();
            document.getElementById('readerView').classList.remove('active');
            if (activeTrailPhase) {
                activeTrailPhase = null;
                renderTrails();
            }
        }

        let activeHighlightColor = null;

        function toggleHighlightPalette(event) {
            event?.stopPropagation();
            document.getElementById('highlightPalette')?.classList.toggle('active');
        }

        function selectHighlightColor(color, darkColor) {
            activeHighlightColor = document.documentElement.dataset.theme === 'dark' ? darkColor : color;
            document.querySelectorAll('.highlight-color').forEach(button => {
                button.classList.toggle('active', button.dataset.color === color);
            });
            document.querySelector('.reader-highlight-btn')?.classList.add('is-selected');
            const palette = document.getElementById('highlightPalette');
            palette?.classList.remove('active');
        }

        function applyCurrentHighlight() {
            if (!activeHighlightColor) return;
            const selection = window.getSelection();
            const content = document.getElementById('readerContent');
            if (!selection || !selection.rangeCount || !selection.toString().trim() || !content) {
                return;
            }
            const range = selection.getRangeAt(0);
            if (!content.contains(range.commonAncestorContainer)) return;
            const mark = document.createElement('span');
            mark.className = 'reader-highlight-mark';
            mark.style.backgroundColor = activeHighlightColor;
            mark.style.color = document.documentElement.dataset.theme === 'dark' ? '#F8FAFC' : 'inherit';
            try {
                range.surroundContents(mark);
            } catch (_) {
                const fragment = range.extractContents();
                mark.appendChild(fragment);
                range.insertNode(mark);
            }
            selection.removeAllRanges();
            const selectedRange = document.createRange();
            selectedRange.selectNodeContents(mark);
            selection.addRange(selectedRange);
        }

        function disableHighlightMode() {
            activeHighlightColor = null;
            document.querySelector('.reader-highlight-btn')?.classList.remove('is-selected');
            document.querySelectorAll('.highlight-color').forEach(button => button.classList.remove('active'));
            document.getElementById('highlightPalette')?.classList.remove('active');
        }

        document.getElementById('readerContent').addEventListener('mouseup', () => {
            window.setTimeout(applyCurrentHighlight, 180);
        });
        document.getElementById('readerContent').addEventListener('touchend', () => {
            // Aguarda o iOS concluir a seleção e exibir seus controles antes
            // de transformar o trecho em marcação, evitando roubar o gesto.
            window.setTimeout(applyCurrentHighlight, 500);
        }, { passive: true });

        document.addEventListener('click', event => {
            if (!event.target.closest('.reader-highlight-wrap')) {
                document.getElementById('highlightPalette')?.classList.remove('active');
            }
        });

        document.getElementById('readerContent').addEventListener('scroll', watchReaderScroll);
        window.addEventListener('pagehide', saveCurrentReaderPosition);

        function buildChapterListPanel() {
            const topic = RAPID_REVIEW_DATA[readerState.topicKey];
            const body = document.getElementById('chapterListBody');
            if (!topic) { body.innerHTML = ''; return; }

            body.innerHTML = topic.sections.map((section, sIdx) => {
                const isCurrentSection = sIdx === readerState.sectionIndex;
                const subitemsHtml = section.subchapters.map((sub, subIdx) => {
                    const isCurrent = isCurrentSection && subIdx === readerState.subIndex;
                    return `<div class="chapter-subitem${isCurrent ? ' current' : ''}" onclick="selectSubchapter(${sIdx}, ${subIdx})">
                        <span class="chapter-subitem-num">${sub.num}</span>
                        <span>${sub.title}</span>
                    </div>`;
                }).join('');

                return `<div class="chapter-section${isCurrentSection ? ' expanded' : ''}" data-section="${sIdx}">
                    <div class="chapter-section-title" onclick="toggleChapterSection(${sIdx})">
                        <span>${section.title}</span>
                        <svg class="chapter-section-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9l6 6 6-6"/></svg>
                    </div>
                    <div class="chapter-subitems">${subitemsHtml}</div>
                </div>`;
            }).join('');
        }

        function toggleChapterSection(sIdx) {
            const el = document.querySelector(`.chapter-section[data-section="${sIdx}"]`);
            if (el) el.classList.toggle('expanded');
        }

        function selectSubchapter(sIdx, subIdx) {
            closeChapterList();
            const block = document.getElementById(`rr-block-${sIdx}-${subIdx}`);
            if (block) block.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }

        function openChapterList() {
            buildChapterListPanel();
            document.getElementById('chapterListPanel').classList.add('active');
            document.getElementById('chapterListBackdrop').classList.add('active');
        }

        function closeChapterList() {
            document.getElementById('chapterListPanel').classList.remove('active');
            document.getElementById('chapterListBackdrop').classList.remove('active');
        }

        // Tamanho do texto do Rapid Review — vale só para o conteúdo lido
        // (não afeta o resto do app), e fica salvo entre visitas. 7 passos,
        // do bem pequeno ao bem grande, controlados por um slider único.
        const READER_FONT_KEY = 'trycktrack-reader-fontsize';
        const READER_FONT_STEPS = [12, 14, 16, 18, 20, 23, 26];
        const QUESTION_FONT_KEY = 'trycktrack-question-fontsize';
        let fontSizeSheetTarget = 'reader';

        function syncFontSizeSlider(px) {
            const idx = READER_FONT_STEPS.indexOf(px);
            const slider = document.getElementById('fontsizeSlider');
            if (slider && idx !== -1) {
                slider.value = idx;
                slider.style.setProperty('--fill', `${(idx / (READER_FONT_STEPS.length - 1)) * 100}%`);
            }
        }

        function applyReaderFontSize(px) {
            document.getElementById('readerContent').style.fontSize = px + 'px';
            syncFontSizeSlider(px);
        }

        function setReaderFontSize(px) {
            localStorage.setItem(READER_FONT_KEY, String(px));
            applyReaderFontSize(px);
        }

        function onFontSizeSlide(stepIndex) {
            const size = READER_FONT_STEPS[Number(stepIndex)];
            if (fontSizeSheetTarget === 'question') setQuestionFontSize(size);
            else setReaderFontSize(size);
        }

        function openFontSizeSheet() {
            fontSizeSheetTarget = 'reader';
            const stored = Number(localStorage.getItem(READER_FONT_KEY)) || 16;
            applyReaderFontSize(stored);
            document.getElementById('fontsizeSheet').classList.remove('question-fontsize-active');
            document.getElementById('fontsizeBackdrop').classList.remove('question-fontsize-active');
            document.getElementById('fontsizeSheet').classList.add('active');
            document.getElementById('fontsizeBackdrop').classList.add('active');
        }

        function applyQuestionFontSize(px) {
            const player = document.getElementById('questionPlayer');
            if (player) player.style.setProperty('--question-font-size', `${px}px`);
            syncFontSizeSlider(px);
        }

        function setQuestionFontSize(px) {
            localStorage.setItem(QUESTION_FONT_KEY, String(px));
            applyQuestionFontSize(px);
        }

        function openQuestionFontSizeSheet() {
            fontSizeSheetTarget = 'question';
            applyQuestionFontSize(Number(localStorage.getItem(QUESTION_FONT_KEY)) || 16);
            document.getElementById('fontsizeSheet').classList.add('question-fontsize-active');
            document.getElementById('fontsizeBackdrop').classList.add('question-fontsize-active');
            document.getElementById('fontsizeSheet').classList.add('active');
            document.getElementById('fontsizeBackdrop').classList.add('active');
        }

        function closeFontSizeSheet() {
            document.getElementById('fontsizeSheet').classList.remove('active');
            document.getElementById('fontsizeBackdrop').classList.remove('active');
            document.getElementById('fontsizeSheet').classList.remove('question-fontsize-active');
            document.getElementById('fontsizeBackdrop').classList.remove('question-fontsize-active');
        }

        // Alça arrastável: puxar pra baixo acompanha o dedo em tempo real;
        // solta perto do topo volta pro lugar, solta mais embaixo (ou com
        // gesto rápido) fecha o menu.
        (function setupFontSizeSheetDrag() {
            const sheet = document.getElementById('fontsizeSheet');
            const handle = document.getElementById('fontsizeSheetHandle');
            let startY = 0;
            let currentY = 0;
            let dragging = false;

            handle.addEventListener('touchstart', (e) => {
                dragging = true;
                startY = e.touches[0].clientY;
                currentY = 0;
                sheet.classList.add('dragging');
            }, { passive: true });

            handle.addEventListener('touchmove', (e) => {
                if (!dragging) return;
                currentY = Math.max(0, e.touches[0].clientY - startY);
                sheet.style.transform = `translateY(${currentY}px)`;
            }, { passive: true });

            handle.addEventListener('touchend', () => {
                if (!dragging) return;
                dragging = false;
                sheet.classList.remove('dragging');
                sheet.style.transform = '';
                if (currentY > 70) {
                    closeFontSizeSheet();
                }
            });
        })();

        // Arrastar da borda direita da tela para a esquerda abre o
        // sumário de temas — como o gesto de abrir uma gaveta.
        (function setupEdgeSwipeToChapterList() {
            const view = document.getElementById('readerView');
            const EDGE_WIDTH = 28;
            let startX = 0;
            let startY = 0;
            let tracking = false;

            view.addEventListener('touchstart', (e) => {
                const t = e.touches[0];
                tracking = t.clientX >= window.innerWidth - EDGE_WIDTH;
                startX = t.clientX;
                startY = t.clientY;
            }, { passive: true });

            view.addEventListener('touchend', (e) => {
                if (!tracking) return;
                tracking = false;
                const t = e.changedTouches[0];
                const dx = t.clientX - startX;
                const dy = Math.abs(t.clientY - startY);
                if (dx < -60 && dy < 60) {
                    openChapterList();
                }
            });
        })();

        function toggleSidebar() {
            document.getElementById('sidebar').classList.toggle('active');
            document.getElementById('sidebarBackdrop').classList.toggle('active');
        }

